Below is a simple example of sending messages to users. It uses a dictionary to store the users and their messages. The users are stored in a dictionary with their names as keys and their messages as values.

```python
import socket
import threading
import time
import random

class User:
    def __init__(self name):
        self.name = name
        self messages = []

class UserManager:
    def __init__(self):
        self.users = {}

    def addUser(self, name):
        self.users[name] = User(name)

    def sendMessage(self, name, message):
        if name in self.users:
            self.users[name].messages.append(message)
            print(f"User {name} received message: {message}")
        else:
            print(f"User {name} not found")

def sendToUser(userManager, message):
    print(f"Sending message to user {userManager.users[message]name}: {message}")
    for user in userManager.users.values():
        if user.name == message:
            print(f"Sending message to user {user.name}: {message}")
            time.sleep(1) # wait for 1 second
            print(f"Sending message to user {user.name}: {message}")
            return
    print(f"User {message} not found")

def main():
    userManager = UserManager()

    while True:
        print("\n1 Send message to user")
        print("2 Exit")
        choice = input("Enter your choice: ")

        if choice == "1":
            name = input("Enter user name: ")
            message = input("Enter message: ")
            userManager.addUser(name)
            sendToUser(userManager, message)
        elif choice == "2":
            break
        else:
            print("Invalid choice")

if __name__ == "__main__":
    main()
```

